import * as T from './vendor/three/three.module.js';
import {GLTFLoader} from './vendor/three/loaders/GLTFLoader.js';
import {chooseVoice,loadVoices} from './speech.js';
const scene=new T.Scene();scene.background=new T.Color('#172b36');scene.fog=new T.Fog('#172b36',13,28);
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.75));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;document.body.prepend(renderer.domElement);
const camera=new T.PerspectiveCamera(38,innerWidth/innerHeight,.1,50);camera.position.set(3.3,2.6,5.8);camera.lookAt(0,1,0);
scene.add(new T.HemisphereLight('#dff6ff','#526272',2.5));const sun=new T.DirectionalLight('#ffffff',3);sun.position.set(4,7,4);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);scene.add(sun);const rim=new T.DirectionalLight('#6ee4dc',2);rim.position.set(-4,3,-3);scene.add(rim);
const ground=new T.Mesh(new T.PlaneGeometry(60,60),new T.MeshStandardMaterial({color:'#29424f',roughness:.8}));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);scene.add(new T.GridHelper(30,30,'#517681','#334e5c'));
const root=new T.Group();scene.add(root);let mixer,actions,current='Idle',travel=0,prev=0,token=0;
const caption=document.getElementById('caption');
function play(name){if(!actions)return;if(name!==current){actions[name].reset().play().crossFadeFrom(actions[current],.25,false);current=name;}document.querySelectorAll('[data-action]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.action===name)));caption.textContent={Idle:'自然待机 · 呼吸与重心变化',Walking:'直线行走 · 到达后停下',Talking:'挥手问候 · 播放英语介绍'}[name];}
try{const gltf=await new GLTFLoader().loadAsync('./assets/characters/school-robot.glb');const model=gltf.scene;mixer=new T.AnimationMixer(model);actions=Object.fromEntries(gltf.animations.map(c=>[c.name,mixer.clipAction(c)]));actions.Talking=actions.Wave;actions.Talking.setLoop(T.LoopOnce,1);actions.Talking.clampWhenFinished=true;mixer.addEventListener('finished',e=>{if(e.action===actions.Talking&&current==='Talking')play('Idle');});actions.Idle.play();mixer.update(0);model.updateMatrixWorld(true);const b=new T.Box3().setFromObject(model),scale=1.65/(b.max.y-b.min.y);model.scale.setScalar(scale);model.position.set(-(b.min.x+b.max.x)*scale/2,-b.min.y*scale,-(b.min.z+b.max.z)*scale/2);model.traverse(o=>{if(o.isMesh)o.castShadow=o.receiveShadow=true;});root.add(model);document.getElementById('status').hidden=true;}catch(e){document.getElementById('status').textContent='模型加载失败：'+e.message;console.error(e);}
for(const button of document.querySelectorAll('[data-action]'))button.onclick=async()=>{const id=++token;speechSynthesis.cancel();const name=button.dataset.action;play(name);if(name==='Walking'){travel=0;root.position.set(-2.2,0,0);root.rotation.y=Math.PI/2;}else if(name==='Talking'){root.rotation.y=.3;}if(name==='Talking'){const voices=await loadVoices(speechSynthesis,2000);if(id!==token)return;const u=new SpeechSynthesisUtterance('Welcome to our future school. I can give you information, but you will complete the mission yourself.');u.voice=chooseVoice(voices,localStorage.getItem('campus-voice')||'');u.lang='en-US';u.rate=Number(localStorage.getItem('campus-speech-rate'))||.85;u.onend=u.onerror=()=>{if(id===token)play('Idle');};speechSynthesis.speak(u);}};
renderer.setAnimationLoop(t=>{const dt=Math.min((t-prev)/1000||.016,.05);prev=t;if(mixer)mixer.update(dt);if(current==='Walking'){travel=Math.min(4.4,travel+dt*1.4);root.position.x=-2.2+travel;if(travel>=4.4)play('Idle');}renderer.render(scene,camera);});
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);});addEventListener('pagehide',()=>{token++;speechSynthesis.cancel();});
